<script setup lang="ts">
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ChatLineRound, CopyDocument, Delete, Edit, MagicStick, MoreFilled, Plus, Promotion, Search, Setting, Star, StarFilled } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { MdPreview } from 'md-editor-v3'
import 'md-editor-v3/lib/preview.css'
import { workbenchApi, workbenchMessage } from '../api'
import type { Conversation, Message, Prompt, Provider } from '../types'

const route = useRoute(); const router = useRouter(); const loading = ref(true); const sending = ref(false); const search = ref(''); const draft = ref(''); const conversations = ref<Conversation[]>([]); const current = ref<Conversation | null>(null); const providers = ref<Provider[]>([]); const prompts = ref<Prompt[]>([]); const createOpen = ref(false); const promptOpen = ref(false); const settingsOpen = ref(false); const thread = ref<HTMLElement | null>(null)
const createForm = reactive({ providerId: '', model: '', systemPrompt: '' }); const settings = reactive({ providerId: '', model: '', systemPrompt: '' })
const enabledProviders = computed(() => providers.value.filter((item) => item.enabled)); const activeProvider = computed(() => providers.value.find((item) => item.id === current.value?.providerId))
async function loadLists() { const [chats, models, library] = await Promise.all([workbenchApi.conversations(search.value), workbenchApi.providers(), workbenchApi.prompts()]); conversations.value = chats; providers.value = models; prompts.value = library }
async function loadCurrent(id: string) { loading.value = true; try { current.value = await workbenchApi.conversation(id); await scrollEnd() } catch (error) { ElMessage.error(workbenchMessage(error, '对话加载失败')); await router.replace('/ai-workbench/chat') } finally { loading.value = false } }
async function init() { loading.value = true; try { await loadLists(); const id = String(route.params.id || ''); if (id) await loadCurrent(id); if (typeof route.query.prompt === 'string') { draft.value = route.query.prompt; await router.replace({ path: route.path }) } } catch (error) { ElMessage.error(workbenchMessage(error, '工作台加载失败')) } finally { loading.value = false } }
function newChat() { if (!enabledProviders.value.length) { ElMessage.warning('请先添加并启用一个模型连接'); void router.push('/ai-workbench/providers'); return }; const provider = enabledProviders.value[0]; Object.assign(createForm, { providerId: provider?.id || '', model: provider?.defaultModel || '', systemPrompt: '' }); createOpen.value = true }
function chooseProvider(value: string, target: typeof createForm | typeof settings) { const provider = providers.value.find((item) => item.id === value); if (provider) target.model = provider.defaultModel }
function chooseCreateProvider(value: string) { chooseProvider(value, createForm) }
function chooseSettingsProvider(value: string) { chooseProvider(value, settings) }
async function createChat() { try { const item = await workbenchApi.createConversation({ ...createForm }); createOpen.value = false; await loadLists(); await router.push(`/ai-workbench/chat/${item.id}`) } catch (error) { ElMessage.error(workbenchMessage(error, '创建失败')) } }
async function send() { const content = draft.value.trim(); if (!content || !current.value || sending.value) return; const id = current.value.id; const optimistic: Message = { id: `local-${Date.now()}`, conversationId: id, role: 'user', content, promptTokens: 0, completionTokens: 0, latencyMs: 0, status: 'completed', createdAt: new Date().toISOString() }; current.value.messages ||= []; current.value.messages.push(optimistic); draft.value = ''; sending.value = true; await scrollEnd(); try { current.value.messages.push(await workbenchApi.sendMessage(id, content)); await loadLists() } catch (error) { ElMessage.error(workbenchMessage(error, '模型响应失败')); current.value = await workbenchApi.conversation(id) } finally { sending.value = false; await scrollEnd() } }
async function scrollEnd() { await nextTick(); if (thread.value) thread.value.scrollTop = thread.value.scrollHeight }
async function selectPrompt(item: Prompt) { await workbenchApi.usePrompt(item.id); draft.value = item.content; promptOpen.value = false }
async function pin() { if (!current.value) return; current.value = await workbenchApi.updateConversation(current.value.id, { pinned: !current.value.pinned }); await loadLists() }
async function rename() { if (!current.value) return; try { const result = await ElMessageBox.prompt('输入新的对话名称', '重命名', { inputValue: current.value.title, inputValidator: (value) => Boolean(value.trim()) || '名称不能为空' }); current.value = await workbenchApi.updateConversation(current.value.id, { title: result.value }); await loadLists() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(workbenchMessage(error)) } }
async function remove() { if (!current.value) return; try { await ElMessageBox.confirm(`确定删除“${current.value.title}”吗？`, '删除对话', { type: 'warning' }); await workbenchApi.deleteConversation(current.value.id); current.value = null; await loadLists(); await router.replace('/ai-workbench/chat') } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(workbenchMessage(error, '删除失败')) } }
function openSettings() { if (!current.value) return; Object.assign(settings, { providerId: current.value.providerId, model: current.value.model, systemPrompt: current.value.systemPrompt }); settingsOpen.value = true }
async function saveSettings() { if (!current.value) return; try { current.value = await workbenchApi.updateConversation(current.value.id, { ...settings }); settingsOpen.value = false; ElMessage.success('对话设置已更新') } catch (error) { ElMessage.error(workbenchMessage(error, '保存失败')) } }
async function copy(value: string) { try { await navigator.clipboard.writeText(value); ElMessage.success('已复制') } catch { ElMessage.error('复制失败') } }
watch(() => route.params.id, (id) => { if (typeof id === 'string') void loadCurrent(id); else current.value = null }); onMounted(init)
</script>

<template><div class="ai-chat"><aside><el-button type="primary" :icon="Plus" @click="newChat">新对话</el-button><el-input v-model="search" :prefix-icon="Search" clearable placeholder="搜索对话" @keyup.enter="loadLists" @clear="loadLists" /><div><button v-for="item in conversations" :key="item.id" :class="{ active: item.id === current?.id }" @click="router.push(`/ai-workbench/chat/${item.id}`)"><el-icon><StarFilled v-if="item.pinned" /><ChatLineRound v-else /></el-icon><span><strong>{{ item.title }}</strong><small>{{ item.lastMessage || '还没有消息' }}</small></span><b>{{ item.messageCount }}</b></button></div></aside><section v-loading="loading"><template v-if="current"><header><div><h2>{{ current.title }}</h2><span>{{ activeProvider?.name }} · {{ current.model }}</span></div><div><el-button text :icon="current.pinned ? StarFilled : Star" aria-label="置顶" @click="pin" /><el-dropdown><el-button text :icon="MoreFilled" aria-label="更多" /><template #dropdown><el-dropdown-menu><el-dropdown-item :icon="Edit" @click="rename">重命名</el-dropdown-item><el-dropdown-item :icon="Setting" @click="openSettings">对话设置</el-dropdown-item><el-dropdown-item divided :icon="Delete" @click="remove">删除对话</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header><main ref="thread"><div v-if="!current.messages?.length" class="ai-chat-empty"><span>AI</span><h3>从一个问题开始</h3><p>{{ current.systemPrompt || '选择提示词，或直接输入你想处理的事情。' }}</p></div><article v-for="message in current.messages" :key="message.id" :class="message.role"><span>{{ message.role === 'user' ? '我' : 'AI' }}</span><div><header><strong>{{ message.role === 'user' ? '我' : message.model || '助手' }}</strong><el-button v-if="message.role === 'assistant'" text :icon="CopyDocument" aria-label="复制" @click="copy(message.content)" /></header><MdPreview v-if="message.role === 'assistant'" :id="`ai-message-${message.id}`" :model-value="message.content" preview-theme="github" /><p v-else>{{ message.content }}</p><small v-if="message.role === 'assistant' && message.status === 'completed'">{{ message.latencyMs }} ms · {{ message.promptTokens + message.completionTokens }} tokens</small></div></article><article v-if="sending" class="assistant"><span>AI</span><div class="ai-thinking"><i></i><i></i><i></i></div></article></main><footer><div><el-button text :icon="MagicStick" @click="promptOpen = true">提示词</el-button><small>{{ draft.length }}/20000</small></div><el-input v-model="draft" type="textarea" resize="none" :autosize="{ minRows: 2, maxRows: 6 }" maxlength="20000" placeholder="输入消息" @keydown.ctrl.enter.prevent="send" /><el-button type="primary" :icon="Promotion" circle :loading="sending" aria-label="发送" @click="send" /></footer></template><div v-else class="ai-chat-empty"><span>AI</span><h2>今天想完成什么？</h2><p>选择已有对话，或者创建一个新对话。</p><el-button type="primary" :icon="Plus" @click="newChat">新建对话</el-button></div></section><el-dialog v-model="createOpen" title="新建对话" width="min(520px,94vw)"><el-form label-position="top"><el-form-item label="模型连接"><el-select v-model="createForm.providerId" @change="chooseCreateProvider"><el-option v-for="item in enabledProviders" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item><el-form-item label="模型"><el-input v-model="createForm.model" /></el-form-item><el-form-item label="系统提示词"><el-input v-model="createForm.systemPrompt" type="textarea" :rows="4" /></el-form-item></el-form><template #footer><el-button @click="createOpen=false">取消</el-button><el-button type="primary" @click="createChat">创建</el-button></template></el-dialog><el-drawer v-model="promptOpen" title="选择提示词" size="min(440px,94vw)"><div class="ai-prompt-drawer"><button v-for="item in prompts" :key="item.id" @click="selectPrompt(item)"><strong>{{ item.title }}</strong><p>{{ item.content }}</p></button><el-empty v-if="!prompts.length" description="还没有提示词" /></div></el-drawer><el-drawer v-model="settingsOpen" title="对话设置" size="min(440px,94vw)"><el-form label-position="top"><el-form-item label="模型连接"><el-select v-model="settings.providerId" @change="chooseSettingsProvider"><el-option v-for="item in enabledProviders" :key="item.id" :label="item.name" :value="item.id" /></el-select></el-form-item><el-form-item label="模型"><el-input v-model="settings.model" /></el-form-item><el-form-item label="系统提示词"><el-input v-model="settings.systemPrompt" type="textarea" :rows="8" /></el-form-item><el-button type="primary" class="full-width" @click="saveSettings">保存设置</el-button></el-form></el-drawer></div></template>

<style scoped>
.ai-chat{display:grid;grid-template-columns:270px minmax(0,1fr);height:calc(100vh - 70px);overflow:hidden;background:var(--surface)}.ai-chat>aside{display:flex;flex-direction:column;min-height:0;padding:14px 11px;border-right:1px solid var(--line);background:var(--theme-table-header)}.ai-chat>aside>.el-button{width:100%;margin-bottom:10px}.ai-chat>aside>.el-input{margin-bottom:8px}.ai-chat>aside>div{overflow:auto}.ai-chat>aside button{display:grid;grid-template-columns:20px minmax(0,1fr) 20px;align-items:center;width:100%;min-height:58px;padding:8px;border:0;border-radius:5px;color:var(--ink);text-align:left;background:transparent;cursor:pointer}.ai-chat>aside button:hover,.ai-chat>aside button.active{background:var(--theme-primary-light-9)}.ai-chat>aside button span{min-width:0}.ai-chat>aside strong,.ai-chat>aside small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.ai-chat>aside strong{margin-bottom:4px;font-size:12px}.ai-chat>aside small{color:var(--muted);font-size:10px}.ai-chat>aside b{color:var(--muted);font-size:10px;text-align:right}.ai-chat>section{display:flex;flex-direction:column;min-width:0;min-height:0}.ai-chat>section>header{display:flex;align-items:center;justify-content:space-between;min-height:62px;padding:8px 20px;border-bottom:1px solid var(--line)}.ai-chat>section>header h2{margin-bottom:4px;font-size:14px}.ai-chat>section>header span{color:var(--muted);font-size:10px}.ai-chat>section>main{flex:1;overflow:auto;padding:22px max(20px,calc((100% - 820px)/2))}.ai-chat article{display:grid;grid-template-columns:32px minmax(0,1fr);gap:11px;margin-bottom:22px}.ai-chat article>span,.ai-chat-empty>span{display:grid;place-items:center;width:30px;height:30px;border-radius:6px;color:#fff;background:var(--theme-primary);font-size:10px;font-weight:700}.ai-chat article.user>span{color:var(--ink);background:var(--theme-border)}.ai-chat article>div>header{display:flex;align-items:center;min-height:22px}.ai-chat article>div>header strong{flex:1;font-size:11px}.ai-chat article p{margin-top:6px;font-size:13px;line-height:1.7;white-space:pre-wrap}.ai-chat article>div>small{display:block;margin-top:8px;color:var(--muted);font-size:9px}.ai-chat :deep(.md-editor-preview-wrapper){padding:3px 0;background:transparent}.ai-chat :deep(.md-editor-preview){font-size:13px}.ai-chat>section>footer{position:relative;width:min(850px,calc(100% - 36px));margin:0 auto 16px;padding:6px 46px 7px 10px;border:1px solid var(--line);border-radius:7px;background:var(--surface);box-shadow:0 7px 22px rgba(20,35,30,.07)}.ai-chat>section>footer>div{display:flex;align-items:center;justify-content:space-between;height:26px}.ai-chat>section>footer small{color:var(--muted)}.ai-chat>section>footer .el-textarea :deep(.el-textarea__inner){padding:4px 0;box-shadow:none}.ai-chat>section>footer>.el-button{position:absolute;right:9px;bottom:9px}.ai-chat-empty{display:grid;place-items:center;align-content:center;height:100%;text-align:center}.ai-chat-empty h2,.ai-chat-empty h3{margin:16px 0 6px}.ai-chat-empty p{width:min(460px,90%);color:var(--muted);font-size:12px}.ai-chat-empty>.el-button{margin-top:18px}.ai-thinking{display:flex;gap:5px;padding-top:10px}.ai-thinking i{width:6px;height:6px;border-radius:50%;background:var(--theme-primary-light-3)}.ai-prompt-drawer button{width:100%;margin-bottom:9px;padding:12px;color:var(--ink);text-align:left;background:var(--surface);border:1px solid var(--line);border-radius:5px;cursor:pointer}.ai-prompt-drawer button:hover{border-color:var(--theme-primary)}.ai-prompt-drawer p{display:-webkit-box;overflow:hidden;margin-top:6px;color:var(--muted);font-size:11px;line-height:1.5;-webkit-box-orient:vertical;-webkit-line-clamp:3}@media(max-width:700px){.ai-chat{grid-template-columns:72px minmax(0,1fr)}.ai-chat>aside{padding:8px 5px}.ai-chat>aside>.el-button span,.ai-chat>aside>.el-input,.ai-chat>aside button span,.ai-chat>aside button b{display:none}.ai-chat>aside button{grid-template-columns:1fr;justify-items:center}.ai-chat>section>main{padding:16px 10px}.ai-chat>section>header{padding:8px 10px}.ai-chat>section>header h2{overflow:hidden;max-width:150px;text-overflow:ellipsis;white-space:nowrap}}
</style>
